import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { ordersApi } from '../utils/api';
import toast from 'react-hot-toast';

const CATEGORY_LABELS = {
  starter: 'Starters',
  main: 'Main Courses',
  dessert: 'Desserts',
  beverage: 'Beverages',
  combo: 'Set Meals',
};

export default function OrderModal({ table, staffId, onClose }) {
  const { menu, staff } = useApp();
  const [cart, setCart] = useState([]);
  const [selectedStaff, setSelectedStaff] = useState(staffId || staff[0]?.id || '');
  const [submitting, setSubmitting] = useState(false);

  const waiters = staff.filter((s) => ['waiter', 'manager'].includes(s.role));

  const categories = [...new Set(menu.map((m) => m.category))];

  function addToCart(item) {
    setCart((prev) => {
      const existing = prev.find((c) => c.menuItemId === item.id);
      if (existing) {
        return prev.map((c) => c.menuItemId === item.id ? { ...c, quantity: c.quantity + 1 } : c);
      }
      return [...prev, { menuItemId: item.id, name: item.name, price: item.price, quantity: 1, notes: '' }];
    });
  }

  function removeFromCart(menuItemId) {
    setCart((prev) => prev.filter((c) => c.menuItemId !== menuItemId));
  }

  function changeQty(menuItemId, delta) {
    setCart((prev) =>
      prev
        .map((c) => c.menuItemId === menuItemId ? { ...c, quantity: c.quantity + delta } : c)
        .filter((c) => c.quantity > 0)
    );
  }

  const total = cart.reduce((sum, c) => sum + c.price * c.quantity, 0);

  async function handleSubmit() {
    if (cart.length === 0) { toast.error('Add at least one item'); return; }
    if (!selectedStaff) { toast.error('Select a staff member'); return; }
    setSubmitting(true);
    try {
      await ordersApi.create({
        tableId: String(table.id),
        staffId: selectedStaff,
        items: cart.map(({ menuItemId, quantity, notes }) => ({ menuItemId, quantity, notes })),
      });
      toast.success('Order placed successfully');
      onClose();
    } catch (err) {
      toast.error(err.response?.data?.error || 'Failed to place order');
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal modal-lg" onClick={(e) => e.stopPropagation()}>
        <h3 className="text-xl font-bold text-white mb-4">Place Order — Table {table.id}</h3>

        <div className="flex gap-6 h-[60vh]">
          {/* Menu */}
          <div className="flex-1 overflow-y-auto pr-2">
            {categories.map((cat) => (
              <div key={cat} className="mb-5">
                <h4 className="text-sm font-semibold text-gray-400 uppercase tracking-wider mb-2">
                  {CATEGORY_LABELS[cat] || cat}
                </h4>
                <div className="space-y-2">
                  {menu.filter((m) => m.category === cat).map((item) => (
                    <div
                      key={item.id}
                      className="flex justify-between items-center bg-gray-800 rounded-lg p-3 cursor-pointer hover:bg-gray-700 transition"
                      onClick={() => addToCart(item)}
                    >
                      <div>
                        <p className="text-white font-medium">{item.name}</p>
                        {item.allergens?.length > 0 && (
                          <p className="text-xs text-orange-400">
                            Allergens: {item.allergens.join(', ')}
                          </p>
                        )}
                      </div>
                      <span className="text-emerald-400 font-bold">${item.price.toFixed(2)}</span>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>

          {/* Cart */}
          <div className="w-56 flex flex-col">
            <h4 className="text-sm font-semibold text-gray-400 uppercase tracking-wider mb-2">Order Cart</h4>
            <div className="flex-1 overflow-y-auto space-y-2">
              {cart.length === 0 && (
                <p className="text-gray-500 text-sm">No items yet — click menu items to add</p>
              )}
              {cart.map((item) => (
                <div key={item.menuItemId} className="bg-gray-800 rounded-lg p-2">
                  <p className="text-white text-sm font-medium">{item.name}</p>
                  <div className="flex items-center gap-2 mt-1">
                    <button onClick={() => changeQty(item.menuItemId, -1)} className="w-6 h-6 rounded bg-gray-700 text-white text-xs flex items-center justify-center">-</button>
                    <span className="text-white text-sm">{item.quantity}</span>
                    <button onClick={() => changeQty(item.menuItemId, 1)} className="w-6 h-6 rounded bg-gray-700 text-white text-xs flex items-center justify-center">+</button>
                    <span className="text-emerald-400 text-xs ml-auto">${(item.price * item.quantity).toFixed(2)}</span>
                  </div>
                </div>
              ))}
            </div>

            <div className="border-t border-gray-700 pt-3 mt-3">
              <div className="flex justify-between text-white font-bold mb-3">
                <span>Total</span>
                <span className="text-emerald-400">${total.toFixed(2)}</span>
              </div>
              <select
                className="input w-full mb-3 text-sm"
                value={selectedStaff}
                onChange={(e) => setSelectedStaff(e.target.value)}
              >
                {waiters.map((s) => (
                  <option key={s.id} value={s.id}>{s.name}</option>
                ))}
              </select>
              <button
                onClick={handleSubmit}
                disabled={submitting || cart.length === 0}
                className="btn w-full bg-amber-600 hover:bg-amber-500 text-white disabled:opacity-50"
              >
                {submitting ? 'Placing...' : 'Confirm Order'}
              </button>
              <button onClick={onClose} className="btn w-full mt-2 bg-gray-700 hover:bg-gray-600 text-white">
                Cancel
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
